        + [F("Tanaw ang Dagat ___ mula sa kuwarto ko. (Pacific)", "Pasipiko", ["Silangan", "Timog"], "Pasipiko."), F("Medyo may kamahalan ang presyo pero ___ naman. (worth it)", "sulit", ["tahimik", "payapa"], "sulit."), F("___ ka nag-book? (yesterday: choose the time word, past)", "Kahapon", ["Bukas", "Mamaya"], "kahapon is past."), F("Kailan ka magbu-book? ___ nang umaga. (tomorrow)", "Bukas", ["Kahapon", "Kagabi"], "bukas."), F("Mamayang ___ ang flight ko. (tonight)", "gabi", ["umaga", "linggo"], "mamayang gabi.")]
