# ------------------------------------------------------------------ 3 grammar
_LL = [("Para lamang sa tatlong tao.", "Only for three persons."), ("Limang taong gulang lang siya.", "He is only five years old."), ("Tatlumpu’t pitong kilometro lamang ang layo mula sa kabisera ng Albay.", "It is just thirty-seven kilometers away from the capital of Albay."), ("Tubig na lang.", "Just water.")]
_RR = [("Pati rin po sa mga guro.", "Including also the teachers, sir or ma’am."), ("At libre rin po ang anak ninyo. Libre rin po ang almusal.", "And your child is free too, sir. Breakfast is also free, sir."), ("Malapit din ito sa pamosong Spice Market.", "This is also near the famous Spice Market."), ("Malapit din ito sa daungan.", "This is also near the port."), ("Nandiyan din ang De La Playa.", "De La Playa is also there.")]
_DW = [("Sabi nila wala raw katulad ang Mission Bay Resort at Casino.", "They say Mission Bay Resort and Casino has no equal."), ("Narinig ko na may diskuwento raw kayo para sa mga sundalo.", "I heard that there is a discount for the soldiers."), ("Ikaw daw ang nagtanong tungkol sa resort.", "They say you asked about the resort."), ("Marami raw ang nagpapareserba sa Discovery Bay sa Boracay.", "They say many are making reservations at Discovery Bay in Boracay."), ("Hindi raw mabuti ang manatili sa Taal Vista Lodge.", "They say it is not good to stay at the Taal Vista Lodge.")]
_NM = [("Sundalo ako at guro naman ang asawa ko.", "I’m a soldier and my wife is a teacher."), ("Medyo may kamahalan ang presyo pero sulit naman.", "It’s a bit expensive but (on the other hand) you get your money’s worth."), ("Bumili ka naman ng tiket.", "Please buy a ticket.")]
_ALN = [("Aling mga hotel ang mura?", "Which hotels are cheap?", "modifier (linker)"), ("Alin ang hotel nina Lucas?", "Which is Lucas and company’s hotel?", "with nouns"), ("Alin ang malinis na hotel?", "Which is the clean hotel?", "with adjectives"), ("Alin sa mga ito ang may libreng almusal?", "Which of these has free breakfast?", "with demonstrative pronouns"), ("Alin sa dalawa ang malapit sa paliparan?", "Which of the two is near the airport?", "with numbers"), ("Alin ang pinili mo?", "Which one did you choose?", "with verbs")]
L3 = lesson(
    "C10 L2 · The enclitics lang, rin/din, raw/daw and naman; review of alin",
    "Lang · Rin at din · Raw at daw · Naman · Alin",
    requires=[],
    cards=[
        card("Review: use the earlier enclitics in sentences", "Make your own sentences with sana, yata, muna, kasi and na (open answers, left out). Examples from the last lesson: Sana makarating ang eroplano kaagad; Tiket yata ni Gregorio iyan; Maghintay ka muna; Hindi kami natuloy kasi maulan; Huli na tayo."),
        card("a. Lang/lamang", "Lang is the short form of lamang, which means “only.” Lang is never used to start a sentence. Occasionally na is added to lang, but the meaning does not change; na lang as a phrase is still translated “only” or “just.”", examples=passage(_LL)),
        card("b. Rin/din", "Rin and din are variants. Rin is used after words ending in vowel sounds (a, e, i, o, u and y); din is used with all other sounds. Rin and din mean “also” or “too” in affirmative sentences. In negative sentences they translate as “either” or “neither.” Like lang, rin and din are not used to start a sentence. (Negative sentences begin with the adverb hindi.)", examples=passage(_RR)),
        card("c. Raw/daw", "Raw and daw follow the same rule as rin/din in the choice of r or d. They are used in repeating what has just been said or read and for stating a general truth or a popular saying.", examples=passage(_DW)),
        card("d. Naman", "Naman can mean “instead,” “on the other hand,” “well enough,” “in turn,” or “after all.” It can also convey a mild reproach. It is also used to state something earlier; in such instances the conjunction “and” can be added to the English statement. Context is always a good guide to how it translates. Naman can also indicate “please,” as in Bumili ka naman ng tiket. The verb needs to be in the command form; in Tagalog the infinitive is also the command form.", examples=passage(_NM)),
        card("B. Adverbial time words and phrases", "Past: kahapon, kagabi, noong linggo, noong nakaraang linggo, kamakalawa, kaninang umaga, noong isang linggo, kamakailan (lang). Present: ngayon lang, ngayung-ngayon lang, ngayon din, ngayung-ngayon din, ngayong mga araw na ito, ngayon ding araw na ito. Future: mamaya, mamayang gabi, bukas, bukas nang umaga. For future time words you can surmise that mamayang hapon means “this afternoon,” bukas nang tanghali “tomorrow at lunch time” and bukas nang gabi “tomorrow night.”"),
        card("C. Review of the question word alin", "Using the dialog in Presentation 1B, categorize the sentences by the different uses of alin: with nouns and adjectives, with numbers and demonstrative pronouns, with verbs, and as a modifier (the linker is used). A sorted list:", tables=[table(["Question", "Meaning", "Use"], [list(r) for r in _ALN], say=[0])]),
    ],
    exercises=uniq(
        tr_q(_LL) + rev_q(_LL) + tr_q(_RR) + rev_q(_RR) + tr_q(_DW) + rev_q(_DW) + tr_q(_NM) + rev_q(_NM) + tr_q([(a, b) for a, b, _ in _ALN]) + rev_q([(a, b) for a, b, _ in _ALN])
        + [M(f"Which use of alin is shown in: {q}", u, dd([x[2] for x in _ALN], u), u) for q, _, u in _ALN]
        + [M("What does lang mean?", "only, just", ["also", "they say", "please"], "lang."), M("When is rin used instead of din?", "after words ending in a vowel sound", ["after words ending in a consonant", "at the start of a sentence", "only in questions"], "rin."), M("What do rin and din mean in a negative sentence?", "either or neither", ["also", "only", "again"], "negative."), M("What does raw or daw do?", "reports what was said or read", ["asks a question", "says please", "means only"], "raw/daw."), M("Which enclitic can mean please with a command?", "naman", ["lang", "daw", "rin"], "naman."), M("Can lang start a sentence?", "No", ["Yes", "Only in questions", "Only with na"], "lang."), M("Which word follows a vowel-ending word to mean also?", "rin", ["din", "daw", "lang"], "rin."), M("Which word follows a consonant-ending word to mean they say?", "daw", ["raw", "rin", "din"], "daw."), M("What does mamayang gabi mean?", "tonight", ["last night", "tomorrow night", "this morning"], "mamayang gabi."), M("What does mamayang hapon mean?", "this afternoon", ["tomorrow afternoon", "yesterday afternoon", "tonight"], "mamayang hapon.")]
        + [F("Limang taong gulang ___ siya. (only)", "lang", ["raw", "rin"], "lang."), F("Malapit ___ ito sa daungan. (also; after a consonant sound)", "din", ["rin", "daw"], "after t/n sounds use din."), F("Libre ___ ang almusal. (also; after a vowel sound)", "rin", ["din", "lang"], "after vowels use rin."), F("Marami ___ ang nagpapareserba. (they say; after a vowel sound)", "raw", ["daw", "rin"], "raw."), F("Bumili ka ___ ng tiket. (please)", "naman", ["lang", "daw"], "naman.")]
    ),
)

