_A2 = [("Napakamahal naman ng hotel na ito kaya doon tayo sa Dusit Hotel.", "naman", "This hotel is very expensive so let’s go to Dusit Hotel."), ("Sinabi mo raw na tumawag kami ng taksi at nagmamadali ka.", "raw", "They say you asked us to call a taxi because you were in a hurry."), ("Ikaw lang daw ang naiwan sa kuwarto dahil maysakit ka.", "lang", "You were the only one left in the room because you were sick."), ("Hindi raw sila tumatanggap ng bata sa resort na ito.", "raw", "They say they are not accepting children in this resort."), ("Ikaw na lang ang sumama sa mga turista sa bus na iyan.", "lang", "You are the only one who should go with the tourists in that bus.")]
_A3 = [("Opo, narito na ang susi sa kuwarto ninyo sa room bilang kuwatro singko dos.", "Tama", "Yes, the key to your room, room number 452, is here."), ("Si Jojo naman ang bibili ng pagkain natin bukas.", "Tama", "Jojo will be the one to buy our food tomorrow."), ("Malapit raw ang Manila Hotel sa Marriott Hotel.", "Malapit daw ang Manila Hotel sa Marriott Hotel.", "They say the Manila Hotel is close to the Marriott Hotel (daw after a consonant sound)."), ("Tatlong putahe lang ang nakalista sa restawrang ito.", "Tama", "Only three dishes are listed in this restaurant."), ("Bakit hindi daw nila nilinis ang kuwarto ninyo?", "Bakit hindi raw nila nilinis ang kuwarto ninyo?", "Why is it that they supposedly did not clean your room? (raw after a vowel sound)"), ("Maganda sa resort na iyon kasi natulog rin kami doon.", "Maganda sa resort na iyon kasi natulog din kami roon.", "It is nice at that resort because we also slept there (din after a consonant sound, and roon after a consonant word).")]
