_T5 = [("Sa kuwarto namin, bilang kuwatro otso diyes, maganda ang tanawin sa labas.", "In our room, number four eight ten, the view outside is beautiful."), ("Dalawandaa’t limampung piso lang ang singil nila sa isang gabi dito.", "They charge only two hundred fifty pesos a night here."), ("Isandaa’t limampung tao sa Manila Hotel ang sasama sa Tour of Manila.", "One hundred fifty people at the Manila Hotel will join the Tour of Manila."), ("Mayroon ding libreng almusal dito sa microtel na ito.", "There is also free breakfast here at this Microtel."), ("Malinis rin at mabuti ang serbisyo sa Hotel Dusit sa Maynila.", "The service at Hotel Dusit in Manila is also clean and good.")]
_T6 = [("Gusto rin naming magbakasyon sa Boracay at nag-book kami rito sa Discovery Shores sa Boracay.", "We also wanted to take a vacation in Boracay and we booked here at Discovery Shores in Boracay."), ("May kamahalan daw ang hotel na ito pero itinuloy namin dahil gusto naming mag-enjoy.", "They said this hotel is a bit expensive but we went ahead because we wanted to enjoy ourselves."), ("Sabi rin ng mga kaibigan namin na hindi raw masyadong masarap ang pagkain.", "Our friends also said that the food is reportedly not very delicious."), ("Hindi totoo ito dahil masarap ang pagkain at binigyan din kami ng diskuwento sa restawran.", "This is not true because the food was delicious and we were also given a discount at the restaurant."), ("Mabuti rin ang serbisyo at napakalinis ng mga kuwarto!", "The service was also good and the rooms were so clean!"), ("Nasiyahan kami sa bakasyon namin at babalik rin kami sa Discovery sa susunod na taon.", "We enjoyed our vacation and we will also come back to Discovery next year.")]
