_J = [("Josie", "Ate Marina, may tiket na ako sa PAL sa bakasyon ko.", "Ate Marina, I already have a PAL ticket for my vacation."), ("Marina", "Sa PAL rin kami. Gusto mo ba ng diskuwento sa hotel?", "We are on PAL too. Do you want a discount at the hotel?"), ("Josie", "Opo naman. Gusto ko rin ng diskuwento. May alam po ba kayong hotel?", "Of course. I also want a discount. Do you know of a hotel?"), ("Marina", "Sa Heritage Hotel may diskuwento at maraming amenities.", "At Heritage Hotel there is a discount and many amenities."), ("Josie", "Ganun po ba? Sige, mag-bo-book ako sa Heritage Hotel at malapit nga sa lahat, sa paliparan, sa Great Mall of Asia, at sa pasyalan. Tamang-tama lang ang pagbabakasyon natin!", "Is that so? Okay, I will book at Heritage Hotel and it is close to everything, the airport, Great Mall of Asia and the tourist spots. Our vacation is just perfect!"), ("Marina", "Sa Heritage, beynte singko porsiyento ang diskuwento at libre ang almusal. Isa pa, malinis at maganda rin ang Heritage. Heto, may brochure ako.", "At Heritage the discount is twenty-five percent and breakfast is free. Also, Heritage is clean and beautiful too. Here, I have a brochure.")]
