_S11 = [("Travel agent", "Magandang umaga po. Ito po ang Mabuhay Travel and Tours. Ano po ang maitutulong ko sa inyo?", "Good morning. This is Mabuhay Travel and Tours. How can I help you?"), ("Client", "Magandang umaga rin po. Gusto ko pong mag-book ng hotel para sa dalawang tao.", "Good morning too. I would like to book a hotel for two people."), ("Travel agent", "Kailan po kayo mananatili?", "When will you stay?"), ("Client", "Mula a-diyes hanggang a-kinse ng Mayo.", "From the tenth to the fifteenth of May."), ("Travel agent", "Para sa ilang tao po?", "For how many people?"), ("Client", "Para sa tatlong tao po, ako, ang nanay kong senior citizen at ang tatlong taong gulang kong anak.", "For three people: myself, my mother, who is a senior citizen, and my three-year-old son."), ("Travel agent", "May beynte porsiyentong diskuwento po ang senior citizen at libre po ang anak ninyo.", "The senior citizen has a twenty percent discount and your son stays for free."), ("Client", "Ang galing naman!", "That’s great!"), ("Travel agent", "Mayroon din po kaming libreng internet, gamit sa gym, almusal at hatid-sundo sa paliparan.", "We also have free internet, use of the gym, breakfast and airport pick-up and drop-off.")]
