        + [F("Para sa tatlong tao po: ako, ang nanay kong senior ___ at ang anak ko. (citizen)", "citizen", ["tao", "kuwarto"], "citizen."), F("Dalawang minuto lang ang ___ papunta sa bayan. (walk)", "lakad", ["layo", "tanaw"], "lakad."), F("Kung ganoon, ___ ang presyo. (worth it)", "sulit", ["tahimik", "libre"], "sulit.")]
